 app.querySelector('#student-entry').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);pendingStudentJoin={code:String(data.get('code')).trim(),name:String(data.get('name')).trim()};showAccess('student');msg.textContent='Inicia sesión para ingresar a la partida.'};
