function clock(cy,requestStarted){clockOpen=!!cy&&cy.status==='open';clockPaused=clockOpen&&!!cy.paused_at;pausedSeconds=clockPaused?Math.max(0,Math.ceil((Date.parse(cy.ends_at)-Date.parse(cy.paused_at))/1000)):0;deadlineMonotonic=clockOpen&&!clockPaused?requestStarted+Math.max(0,Date.parse(cy.ends_at)-Date.parse(cy.server_now)):null;updateClock()}
function updateClock(){const el=document.querySelector('#clock');if(!el)return;const active=clockOpen&&(clockPaused||deadlineMonotonic!==null);if(!active){el.textContent='';return}const seconds=clockPaused?pausedSeconds:Math.max(0,Math.ceil((deadlineMonotonic-performance.now())/1000));const processing=!clockPaused&&seconds===0;el.textContent=processing?'Tiempo finalizado':`${clockPaused?'Pausado':'Tiempo oficial'}: ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;const status=document.querySelector('#cycle-status');if(status)status.textContent=clockPaused?'Pausado':processing?'Procesando resultados':'En curso';document.querySelector('#processing-notice')?.classList.toggle('hidden',!processing);document.querySelector('#decision')?.classList.toggle('hidden',processing||clockPaused)}
